  "signal_basis": {
    "component_id": "C018_signal_basis",
    "value": "Candidate alignments are tested against independently supported dates and additional histories. The assumed positive signal is repeated correspondence of distinctive multi-day patterns across overlapping records, agreement with independent date anchors, and consistency with histories withheld from alignment selection.",
    "scope": "Prospective validation of chronological placements. False alignments remain possible, copied records do not provide independent corroboration, and ambiguous or conflicting evidence requires retaining alternatives.",
